-- Étapes détaillées des recettes communes (viandes) (durées, feu, °C, repères de cuisson), pour la fiche « pas à pas » et ses
-- minuteurs. Nouvelle version de chaque recette : la version en cours est recopiée (ingrédients, temps…), seules les étapes
-- changent (data/recipes/seed.json). Idempotent : rien n'est fait si la version portant cette note existe déjà.
do $do$
declare
  r record;
  rid uuid;
  cv public.recipe_versions;
  p jsonb;
begin
  for r in select key as slug, value as steps from jsonb_each($etapes${"poulet-curry-coco":["Rincer le riz basmati, le cuire 11 min dans une grande casserole d'eau bouillante salée, l'égoutter et le garder couvert.","Émincer l'oignon, hacher l'ail et le gingembre. Couper le poulet en morceaux de 3 cm.","Chauffer l'huile à feu moyen dans une sauteuse. Faire fondre l'oignon 3 min sans le colorer, ajouter l'ail, le gingembre et le curry, remuer 1 min jusqu'à ce que les épices sentent bon.","Monter à feu vif, ajouter le poulet et le saisir 4 min en remuant, jusqu'à ce qu'il soit blanc sur toutes les faces.","Verser le lait de coco et les tomates, saler. Laisser mijoter 15 min à feu doux, à petits frémissements, en remuant de temps en temps : la sauce doit napper la cuillère.","Goûter et rectifier le sel. Parsemer de coriandre ciselée et servir avec le riz."],"poulet-citron-pommes-de-terre-four":["Préchauffer le four à 200 °C. Laver les pommes de terre et les couper en quartiers de taille égale.","Dans un grand plat, mélanger les pommes de terre avec l'huile, le thym, l'ail écrasé, du sel et du poivre. Enfourner 20 min à 200 °C.","Pendant ce temps, couper le poulet en gros morceaux et le citron en quartiers.","Sortir le plat, ajouter le poulet et le citron, arroser avec le jus du plat. Remettre au four 25 min à 200 °C en retournant le tout à mi-cuisson.","Vérifier la cuisson : le poulet est doré et son jus est clair quand on le pique, les pommes de terre sont tendres. Presser un quartier de citron rôti au moment de servir."],"fajitas-poulet-poivrons":["Couper le poulet en lanières d'1 cm, les poivrons et l'oignon rouge en fines tranches.","Mélanger le poulet avec le paprika, le cumin, le jus d'un demi citron vert et du sel. Laisser reposer 10 min pendant que vous préparez le reste.","Chauffer l'huile à feu vif dans une grande poêle. Saisir le poulet 5 min en remuant, jusqu'à ce qu'il soit doré.","Ajouter poivrons et oignon, cuire 8 min à feu vif en remuant : les légumes doivent rester légèrement croquants.","Écraser les avocats avec le jus du reste du citron vert et une pincée de sel. Réchauffer les wraps 30 secondes de chaque côté dans une poêle sèche.","Garnir chaque wrap de poulet aux légumes, d'avocat et d'une cuillère de crème, puis rouler."],"poulet-creme-champignons-tagliatelles":["Porter une grande casserole d'eau salée à ébullition. Émincer les échalotes, trancher les champignons.","Faire fondre le beurre à feu moyen-vif dans une grande poêle. Dorer les escalopes 4 min de chaque côté, saler, puis les réserver sur une assiette.","Dans la même poêle à feu moyen, faire revenir les échalotes 2 min, puis les champignons 8 min jusqu'à ce que leur eau soit évaporée et qu'ils dorent.","Plonger les tagliatelles dans l'eau bouillante et les cuire 8 à 10 min (temps du paquet).","Verser la crème dans la poêle, saler, poivrer, remettre le poulet et laisser épaissir 5 min à feu doux.","Égoutter les pâtes, servir avec le poulet nappé de sauce et le persil ciselé."],"poulet-basquaise":["Couper le poulet en morceaux de 4 cm, les poivrons en lanières, émincer l'oignon et l'ail.","Chauffer l'huile d'olive à feu vif dans une cocotte. Dorer le poulet 5 min en le retournant, puis le réserver.","Baisser à feu moyen. Faire fondre l'oignon et les poivrons 10 min en remuant, jusqu'à ce qu'ils soient tendres.","Ajouter l'ail, les tomates, le thym et le paprika. Saler, porter à frémissement.","Remettre le poulet, couvrir et laisser mijoter 25 min à feu doux, en remuant à mi-cuisson.","Pendant ce temps, cuire le riz 11 min dans l'eau bouillante salée et l'égoutter. Servir le poulet avec le riz (piment d'Espelette dans l'assiette des adultes)."],"poulet-yaourt-courgettes-grillees":["Mélanger le yaourt, l'ail râpé, le cumin, le paprika, le jus du citron et du sel. Couper le poulet en morceaux, l'enrober de cette marinade et laisser mariner 20 min au frais (jusqu'à 1 nuit).","Couper les courgettes en rondelles d'1 cm et les huiler légèrement.","Chauffer une poêle-gril à feu vif (ou le four en position gril). Griller le poulet égoutté et les courgettes 10 à 12 min en retournant à mi-cuisson, jusqu'à ce que le poulet soit doré et bien cuit à cœur.","Porter à ébullition le même volume d'eau salée que de semoule. Verser sur la semoule, couvrir et laisser gonfler 5 min.","Égrener la semoule à la fourchette avec un filet d'huile d'olive et servir avec le poulet et les courgettes."],"salade-cesar-poulet":["Chauffer un filet d'huile à feu moyen dans une poêle. Cuire le poulet 5 min de chaque côté, jusqu'à ce que le centre ne soit plus rosé. Saler et laisser tiédir 5 min avant de le trancher.","Préparer la sauce : mélanger le yaourt, la moutarde, le jus du citron, l'huile, la moitié du parmesan râpé et les anchois écrasés.","Laver, essorer et couper la salade en lanières.","Mélanger la salade avec la sauce, ajouter le poulet tranché, les croûtons et le reste du parmesan en copeaux. Servir aussitôt pour garder les croûtons croustillants."],"poulet-soja-miel-brocoli":["Cuire le riz 11 min dans une grande casserole d'eau bouillante salée, l'égoutter.","Détailler le brocoli en fleurettes et les cuire 4 min dans l'eau bouillante salée : elles doivent rester croquantes. Égoutter.","Couper le poulet en dés. Chauffer l'huile à feu vif dans une grande poêle et saisir le poulet 6 min en remuant, jusqu'à ce qu'il soit doré.","Ajouter l'ail et le gingembre râpés, remuer 30 secondes, puis verser la sauce soja et le miel. Laisser réduire 2 min en enrobant le poulet, jusqu'à ce que la sauce brille et devienne sirupeuse.","Ajouter le brocoli, mélanger 1 min, parsemer de sésame et servir avec le riz."],"gratin-poulet-butternut-comte":["Préchauffer le four à 200 °C. Éplucher la courge, retirer les graines et la couper en dés de 2 cm.","Chauffer l'huile à feu moyen dans une poêle. Faire revenir l'oignon émincé et le poulet en dés 5 min, jusqu'à ce que le poulet soit blanc.","Dans un plat à gratin, mélanger la courge, le poulet, la crème, la muscade, du sel et du poivre. Couvrir de comté râpé.","Enfourner 35 min à 200 °C. La courge doit être tendre sous la pointe d'un couteau et le dessus bien doré. Laisser reposer 5 min avant de servir."],"plaque-poulet-patate-douce-fenouil":["Préchauffer le four à 210 °C. Éplucher les patates douces et les couper en cubes de 2 cm, couper le fenouil en quartiers fins et l'oignon en quartiers.","Étaler les légumes sur une plaque recouverte de papier cuisson, avec la moitié de l'huile, du sel et le paprika. Enfourner 15 min à 210 °C.","Couper le poulet en morceaux et l'enrober du reste de l'huile et d'une pincée de sel.","Ajouter le poulet sur la plaque, mélanger et poursuivre la cuisson 20 min à 210 °C, jusqu'à ce que le poulet soit doré et les patates douces tendres.","Servir avec une cuillère de yaourt grec."],"nouilles-sautees-poulet-legumes":["Cuire les nouilles 3 à 4 min dans l'eau bouillante (temps du paquet), les égoutter et les passer sous l'eau froide pour qu'elles ne collent pas.","Couper le poulet en lanières, les carottes en bâtonnets fins, émincer le pak choï et l'oignon nouveau. Hacher l'ail et râper le gingembre.","Chauffer l'huile à feu vif dans un wok ou une grande poêle. Saisir le poulet 4 min en remuant sans arrêt.","Ajouter l'ail, le gingembre et les carottes, cuire 3 min à feu vif.","Ajouter le pak choï, les nouilles et la sauce soja, faire sauter 2 min en mélangeant bien. Parsemer d'oignon nouveau et servir aussitôt."],"dinde-moutarde-haricots-verts":["Cuire les haricots verts 10 min dans une grande casserole d'eau bouillante salée : ils doivent rester légèrement croquants. Égoutter (ou réchauffer 5 min ceux en conserve).","Faire fondre le beurre à feu moyen-vif dans une poêle. Dorer les escalopes 3 min de chaque côté, saler, poivrer et les réserver au chaud sous une assiette.","Dans la même poêle à feu moyen, faire fondre l'échalote émincée 2 min.","Ajouter la crème et la moutarde, mélanger et laisser réduire 3 min à feu doux, jusqu'à ce que la sauce nappe la cuillère.","Remettre les escalopes 1 min dans la sauce pour les réchauffer et servir avec les haricots verts."],"dinde-roulee-jambon-fromage-puree":["Éplucher les pommes de terre, les couper en morceaux et les cuire 20 min dans l'eau salée, départ eau froide, jusqu'à ce que la pointe d'un couteau les traverse facilement.","Aplatir les escalopes entre deux feuilles de papier cuisson. Poser une tranche de jambon et une d'emmental, rouler serré et fermer avec un pique en bois.","Faire fondre la moitié du beurre à feu moyen dans une poêle. Dorer les roulés 5 min en les tournant sur toutes les faces.","Couvrir et poursuivre la cuisson 15 min à feu doux, en retournant à mi-cuisson.","Chauffer le lait 2 min. Égoutter les pommes de terre et les écraser avec le lait chaud, le reste du beurre, la muscade, du sel et du poivre. Retirer les piques et servir."],"magret-canard-pommes-poelees":["Préchauffer le four à 200 °C. Éplucher la patate douce, la couper en cubes de 2 cm, la mélanger au thym avec un peu de sel et la rôtir 30 min à 200 °C.","Sortir les magrets du réfrigérateur 10 min avant la cuisson. Quadriller la peau au couteau sans entailler la chair, saler et poivrer.","Poser les magrets côté peau dans une poêle froide sans matière grasse. Cuire 8 min à feu moyen, en retirant la graisse fondue au fur et à mesure (en garder 1 cuillère).","Retourner les magrets et cuire 4 min côté chair pour une cuisson rosée. Les envelopper dans du papier aluminium et laisser reposer 5 min.","Dans la cuillère de graisse gardée, poêler les pommes en quartiers 6 min à feu moyen avec le miel, jusqu'à ce qu'elles soient dorées et caramélisées.","Trancher les magrets en biais et servir avec les pommes et la patate douce."],"blanquette-poulet-carottes":["Faire fondre le beurre à feu moyen dans une cocotte. Faire revenir le poulet en morceaux et l'oignon émincé 5 min sans les colorer.","Saupoudrer de farine et remuer 1 min pour la cuire.","Mouiller avec 60 cl d'eau et le cube de bouillon émietté, en grattant le fond. Ajouter les carottes en rondelles et le laurier. Laisser mijoter 25 min à feu doux, à couvert.","Ajouter les champignons émincés et poursuivre 10 min. Pendant ce temps, cuire le riz 11 min dans l'eau bouillante salée.","Hors du feu, retirer le laurier, incorporer la crème et le jus du demi-citron. Goûter, rectifier le sel et servir avec le riz."],"quesadillas-poulet-fromage":["Couper le poulet en petits dés et le poivron en petits dés. Égoutter le maïs.","Chauffer l'huile à feu moyen dans une poêle. Cuire le poulet avec le paprika et le poivron 6 min en remuant, jusqu'à ce que le poulet soit cuit à cœur.","Sur la moitié de chaque wrap, répartir le poulet, le maïs et le fromage. Replier en deux.","Dorer les quesadillas dans une poêle sèche à feu moyen, 2 min de chaque côté, jusqu'à ce que le fromage fonde et que la galette croustille.","Couper en triangles et servir avec la salade."],"spaghetti-bolognaise":["Hacher finement l'oignon, la carotte et l'ail.","Chauffer l'huile à feu moyen dans une sauteuse. Faire revenir les légumes 5 min, jusqu'à ce que l'oignon soit translucide.","Monter à feu vif, ajouter la viande et la faire dorer 5 min en l'émiettant à la spatule.","Ajouter les tomates, le concentré et l'origan, saler. Laisser mijoter 30 min à couvert à feu doux, en remuant de temps en temps.","Cuire les spaghetti 9 à 11 min dans une grande casserole d'eau bouillante salée (temps du paquet).","Égoutter les pâtes, les mélanger à la sauce et servir avec le parmesan râpé."],"chili-con-carne":["Couper l'oignon et le poivron en dés, hacher l'ail. Rincer et égoutter les haricots rouges.","Chauffer l'huile à feu moyen dans une cocotte. Faire revenir l'oignon et le poivron 5 min, ajouter l'ail, le cumin et le paprika, remuer 1 min.","Monter à feu vif, ajouter la viande et la faire dorer 5 min en l'émiettant.","Verser les tomates et les haricots, saler. Couvrir et laisser mijoter 35 min à feu doux, en remuant toutes les 10 min.","Cuire le riz 11 min dans l'eau bouillante salée et l'égoutter. Servir le chili avec le riz (le piment dans l'assiette des adultes)."],"hachis-parmentier":["Éplucher les pommes de terre, les couper en morceaux et les cuire 20 min dans l'eau salée, départ eau froide, jusqu'à ce qu'elles soient tendres.","Préchauffer le four à 200 °C. Faire revenir l'oignon émincé 5 min à feu moyen, puis la viande 5 min à feu vif en l'émiettant. Ajouter le concentré de tomate, saler et poivrer.","Chauffer le lait 2 min. Écraser les pommes de terre avec le lait chaud, le beurre et la muscade, saler.","Dans un plat à gratin, étaler la viande puis couvrir de purée. Lisser et parsemer de fromage râpé.","Gratiner 25 min à 200 °C, jusqu'à ce que le dessus soit bien doré. Laisser reposer 5 min avant de servir."],"burgers-maison":["Couper les tomates et l'oignon rouge en rondelles, laver la salade, tailler les carottes en bâtonnets.","Chauffer une poêle à feu vif. Cuire les steaks 3 à 4 min de chaque côté selon l'épaisseur. Poser le cheddar sur les steaks 1 min avant la fin pour qu'il fonde.","Couper les pains en deux et les toaster 1 à 2 min dans la poêle ou au grille-pain.","Monter les burgers : ketchup, salade, steak au cheddar, tomate, oignon et cornichons. Servir avec les bâtonnets de carotte."],"boeuf-bourguignon":["Couper la viande en cubes de 4 cm et l'éponger. Dorer les lardons 3 min à feu moyen dans une cocotte, puis les réserver.","Monter à feu vif et faire dorer la viande en 3 fois, 4 min par fournée, sans trop charger la cocotte. Réserver.","Baisser à feu moyen. Faire revenir l'oignon émincé et l'ail 3 min, remettre la viande et les lardons, saupoudrer de farine et remuer 1 min.","Mouiller avec le vin (ou 50 cl de bouillon), compléter d'eau à hauteur. Ajouter les carottes en rondelles, le thym, le laurier et le cube. Porter à frémissement.","Couvrir et laisser mijoter 2 h à feu très doux : la viande doit se couper à la fourchette.","Ajouter les champignons émincés 20 min avant la fin. Pendant ce temps, cuire les pommes de terre 20 min à la vapeur et servir avec le bourguignon."],"lasagnes-bolognaise":["Bolognaise : faire revenir l'oignon et l'ail hachés 5 min à feu moyen, ajouter la viande et la dorer 5 min à feu vif, puis les tomates et l'origan. Saler et mijoter 20 min à feu doux.","Préchauffer le four à 180 °C.","Béchamel : faire fondre le beurre à feu moyen, ajouter la farine et remuer 1 min. Verser le lait froid en fouettant et cuire 5 min en fouettant sans arrêt jusqu'à épaississement. Saler, ajouter la muscade.","Dans un plat, alterner bolognaise, feuilles de lasagne et béchamel, en finissant par la béchamel couverte de fromage râpé.","Cuire 40 min à 180 °C, jusqu'à ce que le dessus soit doré et que la pointe d'un couteau traverse les pâtes sans résistance. Laisser reposer 10 min avant de couper."],"boulettes-boeuf-sauce-tomate":["Mélanger la viande, l'œuf, la chapelure, le parmesan, la moitié de l'ail haché et du sel. Former une vingtaine de boulettes de la taille d'une noix, les mains mouillées.","Chauffer l'huile à feu moyen-vif dans une sauteuse. Dorer les boulettes 5 min en les retournant délicatement.","Ajouter le coulis et le reste de l'ail, couvrir et laisser mijoter 15 min à feu doux.","Pendant ce temps, cuire les pâtes 9 à 11 min dans l'eau bouillante salée (temps du paquet) et les égoutter.","Servir les boulettes et leur sauce sur les pâtes, avec le basilic ciselé."],"courgettes-farcies-boeuf":["Préchauffer le four à 190 °C. Couper les courgettes en deux dans la longueur, les évider à la cuillère en laissant 5 mm de chair, et hacher la chair retirée.","Chauffer l'huile à feu moyen. Faire revenir l'oignon émincé 3 min, ajouter la viande, la chair de courgette, la tomate en dés et les herbes. Cuire 10 min en émiettant la viande, saler.","Garnir les courgettes de farce, les ranger dans un plat et parsemer de fromage râpé.","Cuire 30 min à 190 °C, jusqu'à ce que les courgettes soient tendres et le fromage gratiné.","Pendant la cuisson, cuire le riz 11 min dans l'eau bouillante salée et l'égoutter. Servir avec les courgettes."],"riz-saute-boeuf-legumes":["Si le riz n'est pas déjà cuit, le cuire 11 min dans l'eau bouillante salée, l'égoutter et l'étaler sur une assiette pour qu'il refroidisse (riz froid = grains bien séparés).","Couper la carotte en petits dés, émincer l'oignon nouveau.","Chauffer l'huile à feu vif dans un wok ou une grande poêle. Saisir la viande 3 min en l'émiettant, ajouter la carotte et les petits pois, cuire 5 min.","Pousser le tout sur le côté, casser les œufs dans l'espace libre et les brouiller 1 min.","Ajouter le riz et la sauce soja, faire sauter 3 min à feu vif en mélangeant bien. Parsemer d'oignon nouveau et servir."],"filet-mignon-moutarde-ancienne":["Préchauffer le four à 200 °C. Couper les pommes de terre en deux, les mélanger avec l'huile, le thym et du sel et les rôtir 30 min à 200 °C.","Saler et poivrer le filet mignon. Le saisir 5 min dans une poêle à feu vif en le tournant sur toutes les faces.","Le poser dans un plat et le cuire 20 min à 200 °C : il doit être juste rosé à cœur. Le laisser reposer 5 min sous une feuille d'aluminium.","Pendant ce temps, cuire les haricots verts 10 min dans l'eau bouillante salée.","Déglacer la poêle du filet avec la crème et la moutarde à feu doux, laisser épaissir 3 min en grattant les sucs.","Trancher le filet, napper de sauce et servir avec les pommes de terre et les haricots."],"quiche-lorraine":["Préchauffer le four à 200 °C. Garnir un moule de la pâte et la piquer à la fourchette.","Faire dorer les lardons 5 min à feu moyen dans une poêle sans matière grasse, les égoutter sur du papier absorbant et les répartir sur la pâte.","Battre les œufs avec la crème, le lait, la muscade et le poivre (pas de sel : les lardons sont salés). Verser sur les lardons et parsemer de fromage.","Cuire 35 min à 200 °C, jusqu'à ce que la quiche soit dorée et gonflée et que le centre ne tremble plus.","Laisser tiédir 5 min avant de découper. Servir avec la salade."],"croque-monsieur-salade":["Préchauffer le four à 220 °C. Beurrer légèrement les tranches de pain sur une face.","Poser 4 tranches face beurrée contre la plaque, les garnir de jambon et d'emmental, puis couvrir avec les autres tranches, face beurrée vers le haut.","Napper le dessus d'un peu de crème et parsemer de fromage râpé.","Cuire 10 min à 220 °C, jusqu'à ce que le dessus soit gratiné (ou dorer à la poêle 3 min de chaque côté à feu moyen).","Préparer la vinaigrette (vinaigre, huile, sel) et assaisonner la salade au dernier moment. Servir avec les croque-monsieur."],"pates-carbonara":["Porter une grande casserole d'eau salée à ébullition et y cuire les spaghetti 9 à 11 min (temps du paquet).","Pendant ce temps, faire dorer les lardons 5 min à feu moyen dans une grande poêle sans matière grasse.","Fouetter les jaunes d'œufs avec le parmesan râpé et beaucoup de poivre.","Égoutter les pâtes en gardant un verre d'eau de cuisson. Hors du feu, les verser dans la poêle des lardons.","Ajouter la préparation aux œufs et mélanger vivement 1 min, en versant un peu d'eau de cuisson pour obtenir une sauce crémeuse (hors du feu pour que les œufs ne cuisent pas en omelette). Servir aussitôt."],"saucisses-lentilles":["Émincer l'oignon et couper les carottes en rondelles. Rincer les lentilles.","Faire revenir l'oignon 3 min à feu moyen dans une cocotte avec un filet d'huile.","Ajouter les lentilles, les carottes, le thym, le laurier, le cube et 80 cl d'eau froide. Porter à ébullition, puis cuire 20 min à feu doux à couvert (ne pas saler avant la fin, les lentilles durciraient).","Piquer les saucisses à la fourchette, les poser sur les lentilles et poursuivre 15 min à couvert à feu doux, jusqu'à ce que les lentilles soient tendres.","Goûter, saler si besoin, retirer le laurier et servir avec la moutarde."],"gratin-pommes-de-terre-jambon-raclette":["Éplucher les pommes de terre et les couper en rondelles de 5 mm. Les cuire 10 min dans l'eau salée bouillante, puis les égoutter délicatement.","Préchauffer le four à 200 °C. Faire fondre l'oignon émincé 5 min à feu moyen avec un filet d'huile.","Dans un plat, alterner les pommes de terre, l'oignon et le jambon en morceaux, verser la crème et poivrer. Couvrir de tranches de raclette.","Cuire 30 min à 200 °C, jusqu'à ce que le fromage soit fondu et doré.","Servir avec la salade."],"galettes-completes":["Faire chauffer une grande poêle à feu moyen avec une noisette de beurre et y poser une galette.","Parsemer de fromage, poser une tranche de jambon et casser un œuf au centre.","Couvrir et cuire 3 à 4 min, jusqu'à ce que le blanc soit pris et le jaune encore coulant.","Replier les bords de la galette en carré et servir aussitôt. Recommencer avec les autres galettes. Servir avec la salade."],"endives-jambon-gratinees":["Retirer le cône amer à la base des endives. Les cuire entières 15 min à la vapeur ou dans l'eau bouillante salée, puis les égoutter en les pressant bien (elles rendent beaucoup d'eau).","Préchauffer le four à 200 °C. Cuire les pommes de terre 20 min à l'eau salée.","Béchamel : faire fondre le beurre à feu moyen, ajouter la farine et remuer 1 min, verser le lait froid en fouettant et cuire 5 min jusqu'à épaississement. Saler, ajouter la muscade.","Rouler chaque endive dans une tranche de jambon, les ranger dans un plat, napper de béchamel et parsemer de fromage.","Gratiner 25 min à 200 °C, jusqu'à ce que le dessus soit bien doré. Servir avec les pommes de terre."],"emince-porc-caramel-soja":["Cuire le riz 11 min et les haricots verts 10 min dans deux casseroles d'eau bouillante salée, puis les égoutter.","Dans une grande poêle, faire fondre le sucre avec 2 cuillères à soupe d'eau à feu moyen, sans remuer, 4 à 5 min jusqu'à obtenir un caramel blond.","Ajouter aussitôt le porc, l'oignon émincé et l'ail haché (attention aux projections). Faire sauter 8 min à feu vif en remuant.","Verser la sauce soja, poivrer et laisser réduire 3 min, jusqu'à ce que la sauce enrobe la viande. Servir avec le riz et les haricots verts."],"pates-chorizo-poivrons":["Porter une grande casserole d'eau salée à ébullition. Couper le chorizo en rondelles, les poivrons en lanières et émincer l'oignon.","Chauffer l'huile à feu moyen dans une sauteuse. Faire revenir le chorizo 2 min, puis ajouter l'oignon et les poivrons et cuire 8 min en remuant.","Ajouter les tomates et laisser mijoter 10 min à feu doux, puis incorporer la crème.","Pendant ce temps, cuire les penne 10 à 11 min (temps du paquet) et les égoutter.","Mélanger les pâtes à la sauce et servir."]}$etapes$::jsonb) loop
    select id into rid from public.recipes where household_id is null and slug = r.slug;
    if rid is null or exists (select 1 from public.recipe_versions where recipe_id = rid and change_note = 'Étapes détaillées : durées, intensité du feu, température du four, repères de cuisson.') then
      continue;
    end if;
    select v.* into cv from public.recipe_versions v join public.recipes c on c.current_version_id = v.id where c.id = rid;
    p := jsonb_build_object(
      'name', cv.name, 'description', cv.description, 'servings', cv.servings, 'prep_min', cv.prep_min, 'cook_min', cv.cook_min,
      'rest_min', cv.rest_min, 'difficulty', cv.difficulty, 'meal_types', to_jsonb(cv.meal_types), 'main_protein', cv.main_protein,
      'cuisine', cv.cuisine, 'seasons', to_jsonb(cv.seasons), 'tags', to_jsonb(cv.tags), 'status', cv.status, 'steps', r.steps,
      'ingredients', (select jsonb_agg(jsonb_build_object('slug', i.slug, 'label', ri.label, 'quantity', ri.quantity, 'unit', ri.unit,
        'base_quantity', ri.base_quantity, 'base_unit', ri.base_unit, 'optional', ri.optional, 'scale', ri.scale_mode) order by ri.position)
        from public.recipe_ingredients ri left join public.ingredients i on i.id = ri.ingredient_id where ri.version_id = cv.id));
    perform private.insert_recipe_version(rid, p, 'Étapes détaillées : durées, intensité du feu, température du four, repères de cuisson.');
    update public.recipe_versions set created_by = null where recipe_id = rid and change_note = 'Étapes détaillées : durées, intensité du feu, température du four, repères de cuisson.';
  end loop;
end
$do$;
